-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
   SUM(CASE
      WHEN COLLATE(DT_RSTD_SERVICE_BOOKINGS.REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
         THEN DT_RSTD_SERVICE_BOOKINGS.COMP_US_NET_PRICE_AMOUNT
      ELSE 0
   END) AS DV_CA_SERVICE_BOOOKINGS_PCT,
   SUM(CASE
      WHEN COLLATE(DT_RSTD_SERVICE_BOOKINGS.REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
         THEN DT_RSTD_SERVICE_BOOKINGS.ANNUALIZED_US_NET_AMT
      ELSE 0
   END) AS DV_ANNUAL_NET_AMT,
   SUM(CASE
      WHEN COLLATE(DT_RSTD_SERVICE_BOOKINGS.REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
         THEN DT_RSTD_SERVICE_BOOKINGS.MULTIYEAR_US_NET_AMT
      ELSE 0
   END) AS DV_MY_NET_PCT,
   SUM(CAST(0.00 AS DEC(18, 6))) AS ANNUITY_AMT,
   'N' AS TRUE_UP_FLG,
   'AMY' AS BOOKING_TYPE_CD,
   RFDY.FISCAL_YEAR_MONTH_INT AS FISCAL_YEAR_MONTH_INT,
   DT_RSTD_SERVICE_BOOKINGS.DV_SALES_ORDER_LINE_KEY,
   DT_RSTD_SERVICE_BOOKINGS.RU_BK_SERVICE_PROD_SUBGROUP_ID AS RU_BK_SERVICE_PROD_SUBGROUP_ID,
   DT_RSTD_SERVICE_BOOKINGS.DV_ATTRIBUTION_CD,
   DT_RSTD_SERVICE_BOOKINGS.PRODUCT_KEY,
   DT_RSTD_SERVICE_BOOKINGS.SALES_TERRITORY_KEY,
   DT_RSTD_SERVICE_BOOKINGS.SALES_REP_NUMBER AS SALES_REP_NUM,
   DT_RSTD_SERVICE_BOOKINGS.SALES_ORDER_KEY,
   DT_RSTD_SERVICE_BOOKINGS.CONTRACT_DURATION AS DV_CONTRACT_DURATION,
   DT_RSTD_SERVICE_BOOKINGS.SERVICE_CONTRACT_START_DTM AS RU_SERVICE_CONTRACT_START_DTM,
   DT_RSTD_SERVICE_BOOKINGS.SERVICE_CONTRACT_END_DTM AS RU_SERVICE_CONTRACT_END_DTM,
   DT_RSTD_SERVICE_BOOKINGS.ANNUALIZED_FLG AS DV_ANNUALIZED_FLG,
