   RFDY.FISCAL_WEEK_NAME AS FISCAL_WEEK_NAME,
   RFDY.DV_FISCAL_YR_MNTH_WEEK_NUM_INT AS DV_FISCAL_YR_MNTH_WEEK_NUM_INT,
